BG3_CONTAINER_BY_ID = {row[0]: row for row in BG3_CONTAINER_LIST}
BG3_CONTAINER_BY_UUID = {row[1]: row for row in BG3_CONTAINER_LIST}


def containers_by_region():
    """{region_key: [row, ...]}."""
    out = {}
    for row in BG3_CONTAINER_LIST:
        out.setdefault(row[5], []).append(row)
    return out


def containers_by_level():
    """{level: [row, ...]}."""
    out = {}
    for row in BG3_CONTAINER_LIST:
        out.setdefault(row[3], []).append(row)
    return out


def select(acts=None, regions=None, categories=None, named_only=False,
           include_cinematic=False, include_variant=False):
    """Filter helper for sizing a Containersanity option."""
    out = []
    for row in BG3_CONTAINER_LIST:
        if not include_cinematic and "C" in row[13]:
            continue
        if not include_variant and "V" in row[13]:
            continue
        if acts and row[4] not in acts:
            continue
        if regions and row[5] not in regions:
            continue
        if categories and row[12] not in categories:
            continue
        if named_only and "N" not in row[13]:
            continue
        out.append(row)
    return out


def location_name(row):
    """"Emerald Grove: Burlap Sack 2 (195, 471)" - region, label, (x, z)."""
    region = REGION_DISPLAY.get(row[5], row[5])
    return f"{region}: {row[7]} ({row[8]:.0f}, {row[10]:.0f})"
